DROP TABLE IF EXISTS water_sources;

CREATE TABLE water_sources (
    id INTEGER PRIMARY KEY,
    amount_tsh DOUBLE PRECISION,
    date_recorded DATE,
    funder VARCHAR(100),
    gps_height INTEGER,
    installer VARCHAR(100),
    longitude DOUBLE PRECISION,
    latitude DOUBLE PRECISION,
    wpt_name VARCHAR(100),
    num_private INTEGER,
    basin VARCHAR(100),
    subvillage VARCHAR(100),
    region VARCHAR(100),
    region_code INTEGER,
    district_code INTEGER,
    lga VARCHAR(100),
    ward VARCHAR(100),
    population INTEGER,
    public_meeting BOOLEAN,
    recorded_by VARCHAR(100),
    scheme_management VARCHAR(100),
    scheme_name VARCHAR(100),
    permit BOOLEAN,
    construction_year INTEGER,
    extraction_type VARCHAR(100),
    extraction_type_group VARCHAR(100),
    extraction_type_class VARCHAR(100),
    management VARCHAR(100),
    management_group VARCHAR(100),
    payment VARCHAR(100),
    payment_type VARCHAR(100),
    water_quality VARCHAR(100),
    quality_group VARCHAR(100),
    quantity VARCHAR(100),
    quantity_group VARCHAR(100),
    source VARCHAR(100),
    source_type VARCHAR(100),
    source_class VARCHAR(100),
    waterpoint_type VARCHAR(100),
    waterpoint_type_group VARCHAR(100)
);






